def run_stream_checker(words, stream):
    root = {}
    max_len = 0

    for word in words:
        max_len = max(max_len, len(word))
        node = root
        for ch in reversed(word):
            node = node.setdefault(ch, {})
        node['$'] = True

    buffer = []
    results = []

    for ch in stream:
        buffer.append(ch)
        if len(buffer) > max_len:
            buffer.pop(0)

        node = root
        found = False
        for c in reversed(buffer):
            if c not in node:
                break
            node = node[c]
            if node.get('$'):
                found = True
                break
        results.append(found)

    return results

